// ===== 动效库（全量内联：引擎的查表引用所有 id） =====

// 动效公共工具（生成器总是内联）
const clampOpt = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
const easeOut = (p: number) => 1 - Math.pow(1 - p, 3);

// 弹入：带回弹，快节奏首选
const m_pop = (f: number, from: number, dur: number): any => {
  const s = spring({ frame: f - from, fps: 30, durationInFrames: dur, config: { damping: 13, stiffness: 260, mass: 0.7 } });
  return { transform: `translateY(${(1 - s) * 28}px) scale(${0.6 + 0.4 * s})`, opacity: interpolate(f, [from, from + 6], [0, 1], clampOpt) };
};
const D_pop = 14;

// 柔和上浮
const m_rise = (f: number, from: number, dur: number): any => {
  const p = interpolate(f, [from, from + dur], [0, 1], clampOpt);
  return { transform: `translateY(${(1 - easeOut(p)) * 60}px)`, opacity: p };
};
const D_rise = 18;

// 盖章冲击
const m_stamp = (f: number, from: number, dur: number): any => {
  const s = spring({ frame: f - from, fps: 30, durationInFrames: dur, config: { damping: 18, stiffness: 420, mass: 0.9 } });
  return { transform: `scale(${1.8 - 0.8 * s}) rotate(${(1 - s) * -18}deg)`, opacity: interpolate(f, [from, from + 4], [0, 1], clampOpt) };
};
const D_stamp = 16;

const m_slideLeft = (f: number, from: number, dur: number): any => {
  const p = interpolate(f, [from, from + dur], [0, 1], clampOpt);
  return { transform: `translateX(${(1 - easeOut(p)) * -160}px)`, opacity: p };
};
const D_slideLeft = 16;

const m_slideRight = (f: number, from: number, dur: number): any => {
  const p = interpolate(f, [from, from + dur], [0, 1], clampOpt);
  return { transform: `translateX(${(1 - easeOut(p)) * 160}px)`, opacity: p };
};
const D_slideRight = 16;

// 翻转揭示，适合对比
const m_flip = (f: number, from: number, dur: number): any => {
  const p = interpolate(f, [from, from + dur], [0, 1], clampOpt);
  return { transform: `perspective(1000px) rotateX(${(1 - p) * 88}deg) scale(${0.9 + 0.1 * p})`, opacity: p };
};
const D_flip = 18;

// 逐字显现（调用方按 typing 比例裁剪）
const m_typeIn = (f: number, from: number, dur: number): any => ({
  transform: 'none', opacity: 1, typing: interpolate(f, [from, from + dur], [0, 1], clampOpt),
});
const D_typeIn = 24;

const m_fade = (f: number, from: number, dur: number): any => {
  const p = interpolate(f, [from, from + dur], [0, 1], clampOpt);
  return { transform: 'none', opacity: p };
};
const D_fade = 12;

const m_drop = (f: number, from: number, dur: number): any => {
  const s = spring({ frame: f - from, fps: 30, durationInFrames: dur, config: { damping: 12, stiffness: 300, mass: 0.8 } });
  return { transform: `translateY(${(s - 1) * 120}px)`, opacity: interpolate(f, [from, from + 5], [0, 1], clampOpt) };
};
const D_drop = 16;

// 震动强调，适合钩子/金句
const m_shock = (f: number, from: number, dur: number): any => {
  const s = spring({ frame: f - from, fps: 30, durationInFrames: dur, config: { damping: 9, stiffness: 320, mass: 0.6 } });
  const shake = f < from + dur ? Math.sin((f - from) * 2.2) * (1 - s) * 8 : 0;
  return { transform: `translateX(${shake}px) scale(${0.7 + 0.3 * s})`, opacity: interpolate(f, [from, from + 5], [0, 1], clampOpt) };
};
const D_shock = 18;

// 倾斜回摆：天平/权衡从一侧摆到另一侧
const m_tilt = (f: number, from: number, dur: number): any => {
  const s = spring({ frame: f - from, fps: 30, durationInFrames: dur, config: { damping: 11, stiffness: 220, mass: 0.9 } });
  return { transform: `rotate(${(1 - s) * -10 + s * 4}deg)`, opacity: interpolate(f, [from, from + 5], [0, 1], clampOpt) };
};
const D_tilt = 20;



