const c_quote = (it: any, w: number, h: number, s: any, ctx: any): React.ReactNode => {
  const lines = (it.t || '').split('\n');
  return <div style={{ ...BOX(s), width: w, height: h, background: s.quoteBg, borderRadius: s.r, boxShadow: s.cardShade, padding: '18px 30px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', gap: 9, borderLeft: `6px solid ${s.accents.amber}`, textAlign: 'center', overflow: 'hidden' }}>
    {lines.map((l: string, i: number) => <div key={i} style={{ color: s.quoteText, fontSize: (it.size || 26) * 1.25, lineHeight: 1.4, fontWeight: 750, clipPath: ctx.typing !== undefined && i === lines.length - 1 ? `inset(0 ${(1 - ctx.typing) * 100}% 0 0)` : undefined }}>{l}</div>)}
  </div>;
};

const c_stamp = (it: any, w: number, h: number, s: any, ctx: any): React.ReactNode => {
  const c = AC(s, it.accent || 'red');
  return <div style={{ ...BOX(s), width: 190, height: 190, transform: `rotate(${ctx.rot}deg)`, border: `7px double ${c}`, borderRadius: '50%', color: c, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 36, fontWeight: 900, textAlign: 'center', padding: 14, opacity: 0.92 }}>{it.badge || it.t}</div>;
};

const c_sticky = (it: any, w: number, h: number, s: any, ctx: any): React.ReactNode => {
  const c = AC(s, it.accent || 'amber');
  return <div style={{ ...BOX(s), width: w, height: h, transform: `rotate(${ctx.rot}deg)`, background: `${c}1A`, border: `2.5px solid ${c}`, borderRadius: s.r, boxShadow: s.cardShade, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 12, color: c, fontSize: it.size || (it.t?.length > 6 ? 26 : 34), fontWeight: 800, textAlign: 'center', lineHeight: 1.25 }}>{it.t}</div>;
};

const c_table = (it: any, w: number, h: number, s: any, ctx: any): React.ReactNode => (
  <div style={{ ...BOX(s), width: w, height: h, background: s.card, border: `2px solid ${s.cardBorder}`, borderRadius: s.r, boxShadow: s.cardShade, padding: 14, display: 'flex', flexDirection: 'column', gap: 8 }}>
    {(it.items || []).map((row: any, i: number) => <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '10px 16px', background: i % 2 ? s.paper : s.paperDeep, borderRadius: s.rSm }}>
      {row.icon && <Icon name={row.icon} color={AC(s, it.accent)} size={24} />}
      <span style={{ color: s.ink, fontSize: it.size || 24, fontWeight: 750 }}>{row.t}</span>
      {row.d && <span style={{ marginLeft: 'auto', color: s.inkSoft, fontSize: 19 }}>{row.d}</span>}
    </div>)}
  </div>
);

const c_tick = (it: any, w: number, h: number, s: any, ctx: any): React.ReactNode => {
  const ok = it.ok !== false;
  const c = ok ? s.accents.jade : s.accents.red;
  return <div style={{ ...BOX(s), width: w, height: h, background: s.card, border: `2px solid ${s.cardBorder}`, borderRadius: s.rSm, boxShadow: s.cardShade, display: 'flex', alignItems: 'center', gap: 12, padding: '0 16px' }}>
    <span style={{ color: c, fontWeight: 900, fontSize: 26 }}>{ok ? '✓' : '✕'}</span>
    <span style={{ color: ok ? s.ink : s.inkSoft, fontSize: it.size || 25, fontWeight: 650 }}>{it.t}</span>
  </div>;
};

const c_trioSticky = (it: any, w: number, h: number, s: any, ctx: any): React.ReactNode => {
  const notes = [
    { label: '第一步', text: it.t1 || '定向', color: s.accents.amber },
    { label: '第二步', text: it.t2 || '深挖', color: s.accents.blue },
    { label: '第三步', text: it.t3 || '借力', color: s.accents.rose },
  ];
  return <div style={{ ...BOX(s), width: w, height: h }}>
    <div style={{ position: 'absolute', left: 16, top: 96, display: 'flex', gap: 24 }}>
      {notes.map((n, i) => <div key={i} style={{ width: 300, height: 218, background: `${n.color}33`, border: `3px solid ${n.color}`, borderRadius: s.r, boxShadow: s.cardShade, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 12, transform: `rotate(${[0, -2, 2][i]}deg)`, boxSizing: 'border-box' }}>
        <div style={{ color: n.color, fontSize: 22, fontWeight: 800 }}>{n.label}</div>
        <div style={{ color: s.ink, fontSize: it.size || 46, fontWeight: 900 }}>{n.text}</div>
      </div>)}
    </div>
    <div style={{ position: 'absolute', right: 10, top: 4 }}>{c_stamp({ badge: it.badge || '三步', accent: 'red' }, 190, 190, s, { rot: -8 })}</div>
  </div>;
};



